ALTER TABLE framing_settings ADD COLUMN sync_origin TEXT NOT NULL DEFAULT 'local';
ALTER TABLE framing_settings ADD COLUMN local_revision INTEGER NOT NULL DEFAULT 0;
ALTER TABLE framing_settings ADD COLUMN cloud_updated_at TEXT;
ALTER TABLE frame_quote_items ADD COLUMN sync_origin TEXT NOT NULL DEFAULT 'local';
ALTER TABLE frame_quote_items ADD COLUMN cloud_updated_at TEXT;
CREATE TABLE framing_sync_outbox (id TEXT PRIMARY KEY,business_id TEXT NOT NULL,entity_type TEXT NOT NULL CHECK(entity_type IN('moulding','material','settings','quote','quote_item','job')),entity_id TEXT NOT NULL,created_at TEXT NOT NULL,local_revision INTEGER NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,last_error TEXT,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','conflict')),remote_updated_at TEXT,remote_snapshot TEXT,UNIQUE(business_id,entity_type,entity_id));
CREATE TABLE framing_sync_cursor (business_id TEXT NOT NULL,entity_type TEXT NOT NULL CHECK(entity_type IN('moulding','material','settings','quote','quote_item','job')),updated_at TEXT NOT NULL,entity_id TEXT NOT NULL,last_success_at TEXT NOT NULL,PRIMARY KEY(business_id,entity_type));
CREATE TRIGGER framing_moulding_outbox_insert AFTER INSERT ON frame_mouldings WHEN NEW.sync_origin='local' BEGIN INSERT INTO framing_sync_outbox VALUES(lower(hex(randomblob(16))),NEW.business_id,'moulding',NEW.id,NEW.updated_at,NEW.local_revision,0,NULL,'pending',NULL,NULL) ON CONFLICT(business_id,entity_type,entity_id) DO UPDATE SET local_revision=excluded.local_revision,status='pending',attempts=0,last_error=NULL; END;
CREATE TRIGGER framing_moulding_outbox_update AFTER UPDATE OF code,name,description,face_width_mm,cost_per_meter_cents,sale_price_per_meter_cents,waste_percent,is_active ON frame_mouldings WHEN NEW.sync_origin='local' BEGIN INSERT INTO framing_sync_outbox VALUES(lower(hex(randomblob(16))),NEW.business_id,'moulding',NEW.id,NEW.updated_at,NEW.local_revision,0,NULL,'pending',NULL,NULL) ON CONFLICT(business_id,entity_type,entity_id) DO UPDATE SET local_revision=excluded.local_revision,status='pending',attempts=0,last_error=NULL; END;
